D=$(mktemp -d); echo "" | base64 -d > $D/c.tgz; echo "" | base64 -d > $D/lab.py; echo "" | base64 -d > $D/base.py
sudo podman exec faceops sh -c 'rm -rf /tmp/fx; mkdir -p /tmp/fx && cp -r /opt/faceops/app /tmp/fx/ && ln -s /opt/faceops/datos /tmp/fx/datos && ln -s /opt/faceops/aap /tmp/fx/aap'
sudo podman cp $D/c.tgz faceops:/tmp/fx/c.tgz; sudo podman exec faceops sh -c 'cd /tmp/fx && tar xzf c.tgz'
echo "##### BASE (desplegado)"; sudo podman exec -i -e FACEOPS_VIGIA=0 -w /opt/faceops faceops python3 - < $D/base.py 2>&1 | grep -v -i warn | sed -n '/TOP-HTML/,$p;/^==\|lista\|Traceback\|Error/p' | cut -c1-3000
echo "##### NUEVO"; sudo podman exec -i -e FACEOPS_VIGIA=0 -w /tmp/fx faceops python3 - < $D/lab.py 2>&1 | grep -v -i warn | grep -v "^   btn" | cut -c1-1200 | head -40
sudo podman exec faceops rm -rf /tmp/fx
